const FAN_STEP: int = 2731; // 0.2617994 rad = 15 deg in BAM

// 2517: EX VELTIME 0x200000, a=60, s=-999999 (keep entry angle), r=2.0/2.2.
// Entering speed is the configured 0.1 (2506), ramp is the source scalar slope.
xformdef AT4_RAMP(target: fx) {
    step_speed(target, 60 + 65536 * EASE_LINEAR);
}

