// ---------------------------------------------------------------------------
// 2394-2447 BossCard8_at2: 3/3/5/7-way aimed fan at 2.0 (E,N) / 2.5 (H,L).
// etAim(0) resolves A at etOn from the muzzle (= boss position, no offset).
// ANIM(1) birth retreat -4*velocity is applied per bullet along its own angle.
// 2414-2416 %B/%C/%D are dead stores in the source.
// The source restarts this task with killAsync(2) at later phases; the boss
// bumps self_int(0) instead and the stale task drops out of its loop.
// ---------------------------------------------------------------------------
async sub card_at2(epoch: int) {
    var rank: int = global(GVAR_RANK);
    var n: int = 3;     // 2401-2409
    var spd: fx = 2fx;  // 2423-2431
    var gap: int = 80;  // 2434-2443
    if rank >= 2 { n = 5; spd = 2.5fx; gap = 60; }
    if rank >= 3 { n = 7; spd = 2.5fx; gap = 50; }
    var back: fx = 4fx * spd; // ANIM a=1 retreat against spawn speed
    while self_int(0) == epoch {
        var aim: angle = aim_player();
        for i in 0..n {
            var off: int = ((i + 1) / 2) * FAN_STEP;
            if i % 2 != 0 { off = -off; }
            var a: angle = aim + (off as angle);
            _ = fire(TH16_BULLET, 2, $self_x - back * cos(a), $self_y - back * sin(a),
                     spd, a, none, none);
        }
        wait(gap);
    }
}

