}

// ---------------------------------------------------------------------------
// 2488-2539 BossCard8_at4: 24 (E) / 48 way fixed ring, half-step offset (mode 5),
// spawn 0.1 ramping to 2.0 (E,N,H) / 2.2 (L) over 60 frames keeping the angle.
// ANIM(1) retreat 4*0.1 = 0.4px along each bullet's own angle.
// 2518-2520 %B/%C/%D are dead stores in the source.
// ---------------------------------------------------------------------------
async sub card_at4(epoch: int) {
    var rank: int = global(GVAR_RANK);
    var n: int = 24;      // 2495-2504
    var spd: fx = 2fx;    // 2508-2517
    var gap: int = 90;    // 2526-2534
    if rank >= 1 { n = 48; }
    if rank >= 2 { n = 48; }
    if rank >= 3 { n = 48; spd = 2.2fx; gap = 80; }
    var half: int = 32768 / n; // mode 5: pi/N half-way offset
    while self_int(0) == epoch {
        for i in 0..n {
            var a: angle = 90deg + ((((i * 65536) / n) + half) as angle);
            _ = fire(TH16_BULLET, 2, $self_x - 0.4fx * cos(a), $self_y - 0.4fx * sin(a),
                     0.1fx, a, AT4_RAMP(spd), none);
        }
        wait(gap);
    }
}

