async sub boss_card8() {
    set_invuln(65535);
    set_hitbox(25fx);  // Boss() 0030 setHitbox(50,50) circular -> radius 25
    set_hurtbox(28fx); // Boss() 0029 setHurtbox(56,56) circular -> radius 28
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT); // 2297 (entry is already here)
    wait(90);                               // 2302 +90 time label
    spawn card_at();                        // 2307 @BossCard8_at() async 1

    // 2312: ($LIFE > 2400) && ($TIME <= 30*60)
    while $self_hp > 2400 && $self_age <= 1800 { wait(1); }
    clear_bullets_at($self_x, $self_y, 640fx, 0); // 2314
    set_self_int(0, 1);
    spawn card_at2(1);                            // 2315

    // 2320: ($LIFE > 1600) && ($TIME <= 60*60)
    while $self_hp > 1600 && $self_age <= 3600 { wait(1); }
    clear_bullets_at($self_x, $self_y, 640fx, 0); // 2322
    set_self_int(0, 2);                           // 2323 killAsync(2)
    spawn card_at2(2);                            // 2324
    spawn card_at3(2);                            // 2325

    // 2330: ($LIFE > 800) && ($TIME <= 90*60)
    while $self_hp > 800 && $self_age <= 5400 { wait(1); }
    clear_bullets_at($self_x, $self_y, 640fx, 0); // 2332
    set_self_int(0, 3);                           // 2333-2335 killAsync(2/3/4)
    spawn card_at2(3);                            // 2336
    spawn card_at3(3);                            // 2337
    spawn card_at4(3);                            // 2338

    // 2339 %F0 = 1.0f is never read inside this card; 2340-2345 330-frame tail.
    var a: int = 10000;
    while a > 0 {
        a = a - 1;
        wait(330);
    }
    loop { wait(1000); } // 2347-2350
}

async sub pattern() {
